"""specs_s200057.py - Sonnet-w2 ctor-style rows (generated by mkfamCT.py): BASE, the member callees (thiscall, stack args popped by the callee) and the engine-table slots record the SEH chain and the object's vtable word; word results come from random slot returns; fs:[0] compared."""
from pilot import S
from recruits_util import rnd, obj, clear_hooks, hook_rec, pystub, seh_record, seh_chain


def _side(c, o):
    sr = seh_record(c, 2)

    def side(emu, k):
        emu.calllog.append(('vt', emu.r32(o)))
        sr(emu, k)
    return side


def _mk(base, calls, slots, size):
    def gen(c):
        clear_hooks(c)
        seh_chain(c, c.rng.choice([0, 1, 2]))
        r = c.rng
        o = rnd(c, size)
        hook_rec(c, base, 0, ret=r.getrandbits(32), this=True, side=_side(c, o))
        for t, n in calls.items():
            hook_rec(c, t, n, ret=r.getrandbits(32), pop=4 * n, this=True, side=_side(c, o))
        eng = rnd(c, 0x1b00)
        c.emu.w32(0x70039c, eng)
        sl = {k: pystub(c, n, ret=lambda emu, kk: r.getrandbits(32), this=True, side=_side(c, o)) for k, n in slots.items()}
        t = obj(c, 0x40, sl, nslots=0x60) if sl else rnd(c, 0x40)
        c.emu.w32(eng + 0x9b, t)
        return [o]
    return gen


S(0x4a6270, 'GUESS famCT 0x4a6270', 'thiscall', None, ret='eax', gen=_mk(0x469870, {0x4e7160: 0}, {276: 4}, 0x160), note='batch200057')
